"""Observability for one agent utterance's audio delivery.

The recorder emits an outcome-tagged playback duration and counts delivery
failures. Interruptions and cancellations are expected outcomes, not errors.
"""

from __future__ import annotations

import asyncio
import time
from contextlib import contextmanager
from contextvars import ContextVar
from typing import Iterator, Optional

from opentelemetry import trace
from opentelemetry.trace import Span

from rasa.tracing.voice.metrics import (
    InteractionOutcome,
    VoiceComponent,
    VoiceOperation,
    record_operation_failure_metric,
    record_playback_duration_metric,
)
from rasa.tracing.voice.recorders.tts.recorder import (
    get_current_synthesize_speech_recorder,
)
from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.spans import (
    content_capture_enabled,
    set_span_error,
    start_voice_span,
    voice_observability_enabled,
)


class PlayAudioRecorder:
    """Record one agent utterance's audio delivery as spans and metrics.

    The recorder owns the span's event and attribute names, the playback's
    timing, and its terminal outcome. When the wrapped span is non-recording
    (tracing disabled), span writes are skipped while metric bookkeeping
    still runs. A detached recorder emits neither signal.
    """

    def __init__(self, span: Span) -> None:
        # Identity and signal state.
        self.span = span
        self._emit_metrics = True
        # Timing: monotonic mark of the first delivered chunk.
        self._first_chunk_monotonic: Optional[float] = None
        # Delivered-audio totals, stamped on the span at end().
        self._audio_bytes_total = 0
        self._audio_chunk_count = 0
        # Terminal state and metric emission guard.
        self._interrupted = False
        self._cancelled = False
        self._failed = False
        # Ensure terminal metrics are processed at most once per recorder.
        self._terminal_metrics_finalized = False

    @classmethod
    def detached(cls) -> "PlayAudioRecorder":
        """Return a recorder that emits neither spans nor metrics."""
        recorder = cls(trace.INVALID_SPAN)
        recorder._emit_metrics = False
        return recorder

    def record_text(self, text: str) -> None:
        """Stamp the played text, only when content capture is enabled."""
        if self.span.is_recording() and content_capture_enabled():
            self.span.set_attribute(semconv.VOICE_PLAYBACK_TEXT, text)

    def record_chunk_sent(self, num_bytes: int) -> None:
        """Count one chunk delivered to the channel.

        The first delivered chunk marks playback start; totals are stamped
        when the span ends.
        """
        if self._first_chunk_monotonic is None:
            self._first_chunk_monotonic = time.monotonic()
            # Skip only the span write when tracing is disabled.
            if self.span.is_recording():
                self.span.add_event(semconv.EVENT_PLAYBACK_START)
        self._audio_bytes_total += num_bytes
        self._audio_chunk_count += 1

    def record_interrupted(self) -> None:
        """Mark the playback as cut short by the user (barge-in).

        Interruption is an expected outcome, not an error: the span keeps its
        clean status and still finishes when the delivery loop completes.
        """
        if self._interrupted:
            return
        self._interrupted = True
        if self.span.is_recording():
            self.span.add_event(semconv.EVENT_PLAYBACK_INTERRUPTED)
            self.span.set_attribute(semconv.VOICE_INTERRUPTED, True)

    def record_cancelled(self) -> None:
        """Mark the task cancelled; suppresses `voice.playback_finished`."""
        self._cancelled = True
        if self.span.is_recording():
            self.span.add_event(semconv.EVENT_PLAYBACK_CANCELLED)

    def record_error(self, error: BaseException) -> None:
        """Record a delivery failure and mark the span ERROR.

        Only the first error increments the failure counter.
        """
        if self._emit_metrics and not self._failed:
            record_operation_failure_metric(
                component=VoiceComponent.PLAYBACK,
                operation=VoiceOperation.PLAY,
                error=error,
            )
        self._failed = True
        if self.span.is_recording():
            set_span_error(self.span, error)

    def end(self) -> None:
        """End the span, stamp sent-audio totals, and emit terminal metrics."""
        if self.span.is_recording():
            if not self._cancelled:
                self.span.add_event(semconv.EVENT_PLAYBACK_FINISHED)
            self.span.set_attribute(semconv.AUDIO_BYTES_TOTAL, self._audio_bytes_total)
            self.span.set_attribute(semconv.AUDIO_CHUNK_COUNT, self._audio_chunk_count)
        self._emit_terminal_metrics()
        # Always end: mandatory for real spans, a no-op for non-recording ones.
        self.span.end()

    def _emit_terminal_metrics(self) -> None:
        """Emit the outcome-tagged playback duration exactly once.

        The duration needs a first chunk as its starting point, so a playback
        that never delivered a chunk emits nothing here; if it failed, the
        failure was already counted by :meth:`record_error`.
        """
        if not self._emit_metrics or self._terminal_metrics_finalized:
            return
        self._terminal_metrics_finalized = True
        if self._first_chunk_monotonic is None:
            return

        # Resolve overlapping terminal states by precedence.
        if self._failed:
            outcome = InteractionOutcome.ERROR
        elif self._cancelled:
            outcome = InteractionOutcome.CANCELLED
        elif self._interrupted:
            outcome = InteractionOutcome.INTERRUPTED
        else:
            outcome = InteractionOutcome.COMPLETED

        record_playback_duration_metric(
            time.monotonic() - self._first_chunk_monotonic,
            outcome=outcome,
        )


_current_playback_recorder: ContextVar[Optional[PlayAudioRecorder]] = ContextVar(
    "rasa_voice_playback", default=None
)


@contextmanager
def play_audio_span(enabled: bool = True) -> Iterator[PlayAudioRecorder]:
    """Open a `play audio` span around one utterance's audio delivery.

    Uses the current span as its parent. Cancellation records
    `voice.playback_cancelled`; other exceptions mark the span as an error.
    Both propagate to the caller.

    Args:
        enabled: Pass ``False`` for audio that is not part of an utterance
            (pacing silence) to open no span and yield a detached no-op
            recorder. Fully disabled voice observability has the same effect;
            in metrics-only mode the recorder wraps a non-recording span but
            is still bound and tracked.

    Yields:
        The utterance's typed recorder.
    """
    if not enabled or not voice_observability_enabled():
        yield PlayAudioRecorder.detached()
        return

    playback_recorder = PlayAudioRecorder(
        start_voice_span(semconv.SPAN_NAME_PLAY_AUDIO)
    )
    token = _current_playback_recorder.set(playback_recorder)
    try:
        yield playback_recorder
    except asyncio.CancelledError:
        playback_recorder.record_cancelled()
        raise
    except Exception as error:
        playback_recorder.record_error(error)
        raise
    finally:
        synthesized_text = get_current_synthesize_speech_recorder().text
        if synthesized_text:
            playback_recorder.record_text(synthesized_text)
        _current_playback_recorder.reset(token)
        playback_recorder.end()


def get_current_play_audio_recorder() -> PlayAudioRecorder:
    """Return the recorder of the playback in progress.

    Outside playback or when voice observability is disabled, returns a
    detached no-op recorder so callers can record unconditionally.
    """
    playback_recorder = _current_playback_recorder.get()
    if playback_recorder is not None:
        return playback_recorder
    return PlayAudioRecorder.detached()
